    "import pandas as pd\n",
    "import numpy as np\n",
    "from sklearn.linear_model import LinearRegression\n",
    "\n",
    "# 1. 读取数据\n",
    "df = pd.read_excel('data/黄金定价_主数据集.xlsx')\n",
    "df_clean = df.dropna().copy()\n",
    "\n",
    "# 2. 计算黄金的日收益率（用于计算波动率）\n",
    "df_clean['黄金日收益率'] = df_clean['黄金价格'].pct_change()\n",
    "\n",
    "# 3. 定义滚动预测函数（用前252天数据预测下一天）\n",
    "window = 252\n",
    "last_date = df_clean['日期'].iloc[-1]\n",
    "today_data = df_clean.iloc[-1]  # 今天的数据\n",
    "\n",
    "# 取最近252天做滚动回归\n",
    "train_data = df_clean.iloc[-window-1:-1]  # 用于训练的数据（不含今天）\n",
    "X_train = train_data[['美元指数', 'VIX', '美债收益率']]\n",
    "y_train = train_data['黄金价格']\n",
    "\n",
    "model = LinearRegression()\n",
    "model.fit(X_train, y_train)\n",
    "\n",
    "# 用今天的因子数据预测“明天的合理价格”\n",
    "X_today = today_data[['美元指数', 'VIX', '美债收益率']].values.reshape(1, -1)\n",
    "predicted_price_tomorrow = model.predict(X_today)[0]\n",
    "\n",
    "# 4. 计算预期收益率 E(R)\n",
    "today_price = today_data['黄金价格']\n",
    "expected_return = (predicted_price_tomorrow / today_price) - 1\n",
    "expected_return_pct = expected_return * 100  # 转为百分比\n",
    "\n",
    "# 5. 计算波动率（风险）σ（基于最近60天收益率的年化标准差）\n",
    "rolling_std = df_clean['黄金日收益率'].tail(60).std()\n",
    "annualized_volatility = rolling_std * np.sqrt(252)\n",
    "annualized_volatility_pct = annualized_volatility * 100  # 转为百分比\n",
    "\n",
    "print(\"=\" * 50)\n",
    "print(\"📊 黄金资产 - 预期收益与风险测算\")\n",
    "print(\"=\" * 50)\n",
    "print(f\"📅 测算基准日: {last_date.strftime('%Y-%m-%d')}\")\n",
    "print(f\"💰 今日实际金价: {today_price:.2f}\")\n",
    "print(f\"🎯 模型预测明日价格: {predicted_price_tomorrow:.2f}\")\n",
    "print(\"-\" * 50)\n",
    "print(f\"📈 预期日收益率 E(R): {expected_return_pct:.3f}%\")\n",
    "print(f\"📉 年化波动率 (风险 σ): {annualized_volatility_pct:.2f}%\")\n",
    "print(\"=\" * 50)\n",
    "print(\"💡 说明：预期收益率为正，代表模型认为明日看涨；\")\n",
    "print(\"   波动率越大，代表未来价格不确定性越高。\")"
