    "import pandas as pd\n",
    "import numpy as np\n",
    "import matplotlib.pyplot as plt\n",
    "\n",
    "# 设置中文字体（防止图表乱码）\n",
    "plt.rcParams['font.sans-serif'] = ['SimHei', 'Microsoft YaHei', 'Arial Unicode MS']\n",
    "plt.rcParams['axes.unicode_minus'] = False\n",
    "\n",
    "# 1. 读取主数据集\n",
    "df = pd.read_excel('data/黄金定价_主数据集.xlsx')\n",
    "df_clean = df.dropna().copy()\n",
    "\n",
    "# 2. 计算日收益率\n",
    "df_clean['日收益率'] = df_clean['黄金价格'].pct_change()\n",
    "\n",
    "# 3. 计算滚动年化波动率（60天滚动窗口，这是金融行业的常用标准）\n",
    "df_clean['滚动波动率_60天'] = df_clean['日收益率'].rolling(60).std() * np.sqrt(252) * 100\n",
    "\n",
    "# 4. 计算整体平均波动率\n",
    "avg_vol = df_clean['滚动波动率_60天'].mean()\n",
    "max_vol = df_clean['滚动波动率_60天'].max()\n",
    "min_vol = df_clean['滚动波动率_60天'].min()\n",
    "current_vol = df_clean['滚动波动率_60天'].iloc[-1]\n",
    "\n",
    "print(\"=\" * 60)\n",
    "print(\"📊 黄金历史波动率分析报告 (2020-2025)\")\n",
    "print(\"=\" * 60)\n",
    "print(f\"📅 分析时间范围: {df_clean['日期'].min().strftime('%Y-%m-%d')} 至 {df_clean['日期'].max().strftime('%Y-%m-%d')}\")\n",
    "print(\"-\" * 60)\n",
    "print(f\"📉 历史平均年化波动率: {avg_vol:.2f}%\")\n",
    "print(f\"📈 历史最高年化波动率: {max_vol:.2f}%\")\n",
    "print(f\"📉 历史最低年化波动率: {min_vol:.2f}%\")\n",
    "print(f\"🔴 当前最新年化波动率: {current_vol:.2f}%\")\n",
    "print(\"-\" * 60)\n",
    "\n",
    "# 判断当前波动率处于历史什么水平\n",
    "percentile = (df_clean['滚动波动率_60天'] <= current_vol).sum() / len(df_clean['滚动波动率_60天'].dropna()) * 100\n",
    "print(f\"📊 当前波动率处于历史 {percentile:.1f}% 分位数\")\n",
    "if current_vol > avg_vol * 1.3:\n",
    "    print(\"🔴 判断: 当前波动率远高于历史均值，市场处于高风险状态！\")\n",
    "elif current_vol < avg_vol * 0.7:\n",
    "    print(\"🟢 判断: 当前波动率远低于历史均值，市场处于异常平静状态。\")\n",
    "else:\n",
    "    print(\"🟡 判断: 当前波动率处于历史正常波动区间内。\")\n",
    "print(\"=\" * 60)\n",
    "\n",
    "# 5. 绘制波动率走势图（核心可视化）\n",
    "fig, ax = plt.subplots(figsize=(14, 7))\n",
    "\n",
    "# 绘制波动率曲线\n",
    "ax.plot(df_clean['日期'], df_clean['滚动波动率_60天'], \n",
    "        color='orange', linewidth=1.5, label='60日滚动年化波动率')\n",
    "\n",
    "# 添加历史均值线\n",
    "ax.axhline(y=avg_vol, color='red', linestyle='--', linewidth=2, \n",
    "           label=f'历史均值: {avg_vol:.2f}%')\n",
    "\n",
    "# 添加当前值标注（最后一点）\n",
    "last_date = df_clean['日期'].iloc[-1]\n",
    "last_vol = df_clean['滚动波动率_60天'].iloc[-1]\n",
    "ax.scatter(last_date, last_vol, color='red', s=100, zorder=5, \n",
    "           label=f'当前值: {last_vol:.2f}%')\n",
    "ax.annotate(f'当前波动率\\n{last_vol:.2f}%', \n",
    "            xy=(last_date, last_vol),\n",
    "            xytext=(last_date - pd.Timedelta(days=30), last_vol + 5),\n",
    "            arrowprops=dict(arrowstyle='->', color='red'),\n",
    "            fontsize=11, ha='center')\n",
    "\n",
    "# 设置图表格式\n",
    "ax.set_title('黄金价格波动率历史走势 (2020-2025)', fontsize=16, fontweight='bold')\n",
    "ax.set_xlabel('日期', fontsize=12)\n",
    "ax.set_ylabel('年化波动率 (%)', fontsize=12)\n",
    "ax.legend(loc='upper right', fontsize=11)\n",
    "ax.grid(alpha=0.3)\n",
    "ax.set_ylim(0, max_vol * 1.2)\n",
    "\n",
    "# 标记几个重要时期（基于你的数据时间范围）\n",
    "# 如果数据包含2022年，可以标注俄乌冲突；如果包含2020年，标注疫情\n",
    "for label, start, end, color in [\n",
    "    ('🦠 疫情冲击', '2020-02-01', '2020-04-01', 'gray'),\n",
    "    ('⚔️ 地缘冲突/通胀', '2022-02-01', '2022-05-01', 'orange'),\n",
    "    ('🚀 牛市加速', '2024-07-01', '2025-12-30', 'green')\n",
    "]:\n",
    "    # 确保标注时间在数据范围内\n",
    "    if df_clean['日期'].min() <= pd.to_datetime(start) <= df_clean['日期'].max():\n",
    "        ax.axvspan(pd.to_datetime(start), pd.to_datetime(end), \n",
    "                   alpha=0.15, color=color, label=f'关键时期: {label}')\n",
    "\n",
    "plt.tight_layout()\n",
    "plt.savefig('黄金历史波动率分析图.png', dpi=300, bbox_inches='tight')\n",
    "plt.show()\n",
    "\n",
    "print(\"\\n💾 图表已保存为 '黄金历史波动率分析图.png'\")\n",
    "\n",
    "# 6. 附加：统计各年份的平均波动率\n",
    "df_clean['年份'] = df_clean['日期'].dt.year\n",
    "yearly_vol = df_clean.groupby('年份')['滚动波动率_60天'].mean()\n",
    "\n",
    "print(\"\\n📅 各年度平均波动率对比：\")\n",
    "print(\"-\" * 40)\n",
    "for year, vol in yearly_vol.items():\n",
    "    bar = '█' * int(vol / 2)\n",
    "    print(f\"{year}年: {vol:.2f}%  {bar}\")"
