    "import pandas as pd\n",
    "import requests\n",
    "from datetime import datetime\n",
    "import os\n",
    "\n",
    "# ============================================================\n",
    "# 第一步：读取你的原始主数据集（只读，不改动）\n",
    "# ============================================================\n",
    "print(\"📂 正在读取原始数据集...\")\n",
    "original_path = 'data/黄金定价_主数据集.xlsx'\n",
    "df_original = pd.read_excel(original_path)\n",
    "\n",
    "# 确保日期格式统一（去掉时分秒，只保留年月日）\n",
    "df_original['日期'] = pd.to_datetime(df_original['日期']).dt.date\n",
    "\n",
    "print(f\"✅ 原始数据集加载成功！共 {len(df_original)} 条记录\")\n",
    "print(f\"📅 时间范围: {df_original['日期'].min()} 至 {df_original['日期'].max()}\")\n",
    "\n",
    "# ============================================================\n",
    "# 第二步：获取恐惧与贪婪指数（FNG）\n",
    "# ============================================================\n",
    "def fetch_fng_data():\n",
    "    \"\"\"从 alternative.me 获取历史恐惧与贪婪指数\"\"\"\n",
    "    try:\n",
    "        print(\"\\n🌐 正在获取恐惧与贪婪指数...\")\n",
    "        url = 'https://api.alternative.me/fng/?limit=1825'\n",
    "        response = requests.get(url, timeout=10)\n",
    "        response.raise_for_status()\n",
    "        \n",
    "        data = response.json()['data']\n",
    "        df_fng = pd.DataFrame(data)\n",
    "        \n",
    "        # 转换时间戳为标准日期格式\n",
    "        df_fng['日期'] = pd.to_datetime(df_fng['timestamp'].astype(int), unit='s').dt.date\n",
    "        df_fng['fng_value'] = df_fng['value'].astype(float)\n",
    "        df_fng['fng_classification'] = df_fng['value_classification']\n",
    "        \n",
    "        df_fng = df_fng[['日期', 'fng_value', 'fng_classification']]\n",
    "        df_fng = df_fng.sort_values('日期').reset_index(drop=True)\n",
    "        \n",
    "        print(f\"✅ 成功获取 {len(df_fng)} 条FNG数据\")\n",
    "        print(f\"📅 FNG时间范围: {df_fng['日期'].min()} 至 {df_fng['日期'].max()}\")\n",
    "        return df_fng\n",
    "    except Exception as e:\n",
    "        print(f\"❌ FNG数据获取失败: {e}\")\n",
    "        return None\n",
    "\n",
    "df_fng = fetch_fng_data()\n",
    "\n",
    "# ============================================================\n",
    "# 第三步：合并数据（左连接，保留所有黄金记录）\n",
    "# ============================================================\n",
    "if df_fng is not None:\n",
    "    print(\"\\n🔗 正在合并数据...\")\n",
    "    # 左连接：保留原始数据的所有行，匹配日期添加FNG值\n",
    "    df_new = df_original.merge(df_fng, on='日期', how='left')\n",
    "    \n",
    "    # 检查匹配情况\n",
    "    matched_count = df_new['fng_value'].notna().sum()\n",
    "    print(f\"✅ 成功匹配 {matched_count} 条FNG数据到主数据集\")\n",
    "    print(f\"⚠️ 缺失FNG的行数: {len(df_new) - matched_count} 条（非交易日/节假日）\")\n",
    "    \n",
    "    # ============================================================\n",
    "    # 第四步：保存为新文件（绝对不动原文件）\n",
    "    # ============================================================\n",
    "    new_path = 'data/黄金定价_主数据集_含FNG因子.xlsx'\n",
    "    df_new.to_excel(new_path, index=False, engine='openpyxl')\n",
    "    \n",
