    "import pandas as pd\n",
    "import numpy as np\n",
    "from sklearn.decomposition import PCA\n",
    "from sklearn.preprocessing import StandardScaler\n",
    "\n",
    "# 1. 读取你的四因子数据集\n",
    "df = pd.read_excel('data/黄金定价_主数据集_含FNG因子.xlsx')\n",
    "df_clean = df.dropna().copy()\n",
    "\n",
    "# 2. 提取要合并的因子（VIX 和 FNG）\n",
    "# 注意：如果数据尺度差异大（比如 VIX 和 FNG 数值范围不同），必须先标准化！\n",
    "features = ['VIX', 'fng_value']\n",
    "X = df_clean[features]\n",
    "\n",
    "# 标准化（让它们处于同一量级，否则 VIX 数值大，PCA 会忽略 FNG）\n",
    "scaler = StandardScaler()\n",
    "X_scaled = scaler.fit_transform(X)\n",
    "\n",
    "# 3. 执行 PCA（降维到 1 个维度）\n",
    "pca = PCA(n_components=1)\n",
    "emotion_factor = pca.fit_transform(X_scaled)\n",
    "\n",
    "# 4. 将生成的情绪因子添加到数据框中\n",
    "df_clean['emotion_factor'] = emotion_factor\n",
    "\n",
    "# 查看 PCA 的方差解释度（看看这个合并因子保留了原始两个因子多少信息）\n",
    "print(f\"✅ 合并后的情绪因子解释了 VIX 和 FNG 总方差的: {pca.explained_variance_ratio_[0]*100:.2f}%\")\n",
    "print(\"\\n📊 相关性检验：\")\n",
    "print(\"合并因子与 VIX 的相关性:\", df_clean['emotion_factor'].corr(df_clean['VIX']))\n",
