    "import pandas as pd\n",
    "import numpy as np\n",
    "from sklearn.decomposition import PCA\n",
    "from sklearn.preprocessing import StandardScaler\n",
    "from sklearn.linear_model import LinearRegression\n",
    "\n",
    "# ============================================================\n",
    "# 1. 读取数据\n",
    "# ============================================================\n",
    "df = pd.read_excel('data/黄金定价_情绪合并版.xlsx')\n",
    "df_clean = df.dropna().copy()\n",
    "\n",
    "# ============================================================\n",
    "# 2. 提取最新一行数据\n",
    "# ============================================================\n",
    "latest = df_clean.iloc[-1]\n",
    "last_date = latest['日期']\n",
    "\n",
    "# ============================================================\n",
    "# 3. 计算日收益率和滚动波动率\n",
    "# ============================================================\n",
    "df_clean['日收益率'] = df_clean['黄金价格'].pct_change()\n",
    "df_clean['滚动波动率_60天'] = df_clean['日收益率'].rolling(60).std() * np.sqrt(252) * 100\n",
    "\n",
    "# 最近60天\n",
    "recent_60 = df_clean['日收益率'].tail(60)\n",
    "\n",
    "# ============================================================\n",
    "# 4. 用新模型预测明天的价格\n",
    "# ============================================================\n",
    "window = 252\n",
    "train_data = df_clean.iloc[-window-1:-1]\n",
    "X_train = train_data[['美元指数', '美债收益率', 'emotion_factor']]\n",
    "y_train = train_data['黄金价格']\n",
    "\n",
    "model = LinearRegression()\n",
    "model.fit(X_train, y_train)\n",
    "\n",
    "X_today = latest[['美元指数', '美债收益率', 'emotion_factor']].values.reshape(1, -1)\n",
    "predicted_tomorrow = model.predict(X_today)[0]\n",
    "\n",
    "today_price = latest['黄金价格']\n",
    "expected_return = (predicted_tomorrow / today_price - 1) * 100\n",
    "\n",
    "# ============================================================\n",
    "# 5. 输出报告\n",
    "# ============================================================\n",
    "print(\"=\" * 60)\n",
    "print(\"📊 黄金资产风险收益报告（情绪合并版）\")\n",
    "print(\"=\" * 60)\n",
    "\n",
    "print(f\"\\n📅 报告日期: {last_date.strftime('%Y-%m-%d')}\")\n",
    "print(f\"💰 当前金价: {today_price:.2f}\")\n",
    "\n",
    "print(\"\\n\" + \"-\" * 60)\n",
    "print(\"📈 预期收益\")\n",
