    "import pandas as pd\n",
    "import numpy as np\n",
    "import matplotlib.pyplot as plt\n",
    "from sklearn.linear_model import LinearRegression\n",
    "\n",
    "# 设置中文字体（防止图表乱码）\n",
    "plt.rcParams['font.sans-serif'] = ['SimHei', 'Microsoft YaHei', 'Arial Unicode MS']\n",
    "plt.rcParams['axes.unicode_minus'] = False\n",
    "\n",
    "# ============================================================\n",
    "# 1. 读取数据\n",
    "# ============================================================\n",
    "df = pd.read_excel('data/黄金定价_情绪合并版.xlsx')\n",
    "df_clean = df.dropna().copy()\n",
    "\n",
    "# 计算日收益率和滚动波动率\n",
    "df_clean['日收益率'] = df_clean['黄金价格'].pct_change()\n",
    "df_clean['滚动波动率_60天'] = df_clean['日收益率'].rolling(60).std() * np.sqrt(252) * 100\n",
    "\n",
    "# 计算模型拟合价格（用全样本三因子合并模型）\n",
    "X_full = df_clean[['美元指数', '美债收益率', 'emotion_factor']]\n",
    "y_full = df_clean['黄金价格']\n",
    "model_full = LinearRegression()\n",
    "model_full.fit(X_full, y_full)\n",
    "df_clean['拟合价格'] = model_full.predict(X_full)\n",
    "\n",
    "# 提取最新数据\n",
    "latest = df_clean.iloc[-1]\n",
    "last_date = latest['日期']\n",
    "today_price = latest['黄金价格']\n",
    "\n",
    "# 最近60天数据\n",
    "recent_60 = df_clean.tail(60)\n",
    "\n",
    "print(\"=\" * 60)\n",
    "print(\"📊 黄金资产分析报告（含图表）\")\n",
    "print(\"=\" * 60)\n",
    "\n",
    "# ============================================================\n",
    "# 图表1：黄金价格 vs 模型拟合价格（全样本）\n",
    "# ============================================================\n",
    "fig1, ax1 = plt.subplots(figsize=(14, 6))\n",
    "\n",
    "ax1.plot(df_clean['日期'], df_clean['黄金价格'], \n",
    "         color='black', linewidth=1.5, label='实际金价')\n",
    "ax1.plot(df_clean['日期'], df_clean['拟合价格'], \n",
    "         color='blue', linewidth=1.2, linestyle='--', label='模型拟合价格', alpha=0.8)\n",
    "\n",
    "ax1.scatter(last_date, today_price, color='red', s=80, zorder=5, label=f'最新: {today_price:.0f}')\n",
    "\n",
    "ax1.set_title('黄金价格 vs 模型拟合价格（情绪合并三因子模型）', fontsize=14, fontweight='bold')\n",
    "ax1.set_xlabel('日期', fontsize=12)\n",
    "ax1.set_ylabel('价格（美元/盎司）', fontsize=12)\n",
    "ax1.legend(loc='upper left', fontsize=11)\n",
    "ax1.grid(alpha=0.3)\n",
    "\n",
    "r2 = model_full.score(X_full, y_full)\n",
    "ax1.text(0.02, 0.95, f'R² = {r2:.4f}', transform=ax1.transAxes, \n",
    "         fontsize=12, bbox=dict(boxstyle='round', facecolor='white', alpha=0.8))\n",
    "\n",
    "plt.tight_layout()\n",
    "plt.savefig('data/黄金价格_实际vs拟合.png', dpi=300, bbox_inches='tight')\n",
    "plt.show()\n",
    "print(\"💾 已保存: data/黄金价格_实际vs拟合.png\")\n",
    "\n",
    "# ============================================================\n",
    "# 图表2：滚动波动率走势图（含历史均值和当前值标注）\n",
    "# ============================================================\n",
    "fig2, ax2 = plt.subplots(figsize=(14, 6))\n",
    "\n",
    "ax2.plot(df_clean['日期'], df_clean['滚动波动率_60天'], \n",
    "         color='orange', linewidth=1.5, label='60日滚动年化波动率')\n",
    "\n",
    "avg_vol = df_clean['滚动波动率_60天'].mean()\n",
    "ax2.axhline(y=avg_vol, color='red', linestyle='--', linewidth=2, \n",
    "            label=f'历史均值: {avg_vol:.2f}%')\n",
    "\n",
    "current_vol = latest['滚动波动率_60天']\n",
