    "            label=f'当前值: {current_vol:.2f}%')\n",
    "\n",
    "ax2.set_title('黄金价格波动率历史走势', fontsize=14, fontweight='bold')\n",
    "ax2.set_xlabel('日期', fontsize=12)\n",
    "ax2.set_ylabel('年化波动率 (%)', fontsize=12)\n",
    "ax2.legend(loc='upper right', fontsize=11)\n",
    "ax2.grid(alpha=0.3)\n",
    "\n",
    "plt.tight_layout()\n",
    "plt.savefig('data/黄金波动率走势图.png', dpi=300, bbox_inches='tight')\n",
    "plt.show()\n",
    "print(\"💾 已保存: data/黄金波动率走势图.png\")\n",
    "\n",
    "# ============================================================\n",
    "# 图表3：最近60天收益率分布（柱状图）\n",
